def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (ignore it)
        if '+' in v:
            v = v.split('+')[0]

        # Split pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)

        # For sorting: if no prerelease, treat as if prerelease is empty list
        # A version with prerelease sorts before same version without
        # So we need: (major, minor, patch, has_prerelease, prerelease_identifiers)
        # where has_prerelease is False (sorts first) if there's a prerelease, True otherwise

        has_prerelease = len(prerelease_identifiers) > 0

        return (major, minor, patch, has_prerelease, prerelease_identifiers)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

